"""核心转换 + VTF→TGA 导出（零 GUI 依赖，回调驱动）。"""

import shutil
import subprocess
import tempfile
from pathlib import Path
from .parse_vmt import image_size
from .preprocess import apply_preprocess


def _cleanup_generated(path):
    """安全删除生成的文件。"""
    if path.exists():
        try:
            path.unlink()
        except OSError:
            pass


def convert_items(items, settings):
    """将工作项列表转换为 VTF。

    items: list[dict]，每个 dict 结构同 scan_vmts 返回值。
    settings: dict，包含:
        vtfcmd: str, vtf_version: str, color_format: str, alpha_format: str,
        size_enabled: bool, resize_enabled: bool,
        resize_method: str, resize_filter: str,
        preprocess_config: dict{base: dict, normal: dict}
    返回: dict{success: int, fail: int, log: list[str]}
    """
    log = []
    vtfcmd = Path(settings["vtfcmd"])
    version = settings.get("vtf_version", "7.2")
    color_fmt = settings.get("color_format", "DXT1")
    alpha_fmt = settings.get("alpha_format", "DXT5")
    size_on = settings.get("size_enabled", False)
    resize_on = settings.get("resize_enabled", False)
    r_method = settings.get("resize_method", "nearest")
    r_filter = settings.get("resize_filter", "triangle")
    pp_config = settings.get("preprocess_config", {})

    if not vtfcmd.is_file():
        return {"success": 0, "fail": 0, "log": [f"[错误] VTFCmd.exe 不存在: {vtfcmd}"]}

    if size_on:
        for data in items:
            for slot in ("base", "normal"):
                s = data[slot]
                if s["enabled"] and s["checked"]:
                    if not (128 <= s["target_w"] <= 4096 and 128 <= s["target_h"] <= 4096):
                        log.append(f"[错误] {data['vmt_name']} {s['param']} "
                                   f"目标分辨率 {s['target_w']}x{s['target_h']} 越界（128~4096）")
                        return {"success": 0, "fail": 0, "log": log}
        log.append("分辨率: 启用（每项使用自身目标分辨率）")
    else:
        log.append("分辨率: 关闭（保持原始尺寸）")

    queue = []
    for data in items:
        for slot in ("base", "normal"):
            s = data[slot]
            if s["enabled"] and s["checked"]:
                queue.append((data, s, slot))
    if not queue:
        log.append("[错误] 没有勾选任何要替换的项")
        return {"success": 0, "fail": 0, "log": log}

    log.append(f"VTF 参数: 版本={version}, Color={color_fmt} (basetexture), Alpha={alpha_fmt} (bumpmap)")
    if resize_on:
        log.append(f"Resize: method={r_method}, filter={r_filter}")
    else:
        log.append("Resize: 关闭（不附加 -rmethod/-rfilter）")

    temp_dir = None
    success = fail = 0
    try:
        temp_dir = Path(tempfile.mkdtemp(prefix="sp2vtf_"))
        total = len(queue)
        log.append(f"开始转换，共 {total} 项")
        last_vmt = None

        for i, (data, s, slot_name) in enumerate(queue):
            vmt_path = Path(data["vmt_path"])
            if vmt_path != last_vmt:
                log.append(f"=== {vmt_path.name} ===")
                last_vmt = vmt_path

            param = s["param"]
            fmt = color_fmt if param == "$basetexture" else alpha_fmt
            png = Path(s["png"])
            size = s["size"] or image_size(png)
            src_str = f"{size[0]}x{size[1]}" if size else "未知"

            resize_flags = []
            if size_on:
                tgt_str = f"{s['target_w']}x{s['target_h']}"
                resize_flags += ["-resize", "-rwidth", str(s["target_w"]), "-rheight", str(s["target_h"])]
            else:
                tgt_str = src_str
            if resize_on:
                if "-resize" not in resize_flags:
                    resize_flags.append("-resize")
                resize_flags += ["-rmethod", r_method, "-rfilter", r_filter]

            slot_pp = pp_config.get(slot_name, {})
            source = png
            if slot_pp.get("alpha_enabled"):
                try:
                    source = Path(apply_preprocess(png, slot_pp, temp_dir))
                    log.append(f"    预处理: Alpha ({slot_pp['alpha_source']}) → {source.name}")
                except Exception as e:
                    log.append(f"    [失败] 预处理出错: {e}")
                    fail += 1
                    continue

            log.append(f"  {param}: {png.name} [{src_str} → {tgt_str}] -> {fmt}")

            target = vmt_path.parent / (Path(s["rel"]).stem + ".vtf")
            target.parent.mkdir(parents=True, exist_ok=True)

            generated = source.with_suffix(".vtf")
            same_location = generated.resolve() == target.resolve()

            if generated.exists() and not same_location:
                _cleanup_generated(generated)

            cmd = [str(vtfcmd), "-file", str(source), "-output", str(source.parent),
                   "-version", version, "-format", fmt] + resize_flags
            try:
                proc = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
            except (OSError, subprocess.TimeoutExpired) as e:
                log.append(f"    [失败] 调用 VTFCmd 出错: {e}")
                _cleanup_generated(generated)
                fail += 1
                continue

            if proc.returncode != 0 or not generated.exists():
                log.append(f"    [失败] VTFCmd 返回 {proc.returncode}")
                if proc.stderr.strip():
                    log.append(f"    stderr: {proc.stderr.strip()}")
                _cleanup_generated(generated)
                fail += 1
                continue

            if not same_location:
                try:
                    tmp = target.with_suffix(target.suffix + ".tmp")
                    shutil.copy2(str(generated), str(tmp))
                    tmp.replace(target)
                    _cleanup_generated(generated)
                except OSError as e:
                    log.append(f"    [失败] 移动 VTF 失败: {e}")
                    _cleanup_generated(generated)
                    _cleanup_generated(tmp)
                    fail += 1
                    continue

            log.append(f"    [成功] -> {target}")
            success += 1

        log.append(f"==== 完成：成功 {success}，失败 {fail} ====")
    finally:
        if temp_dir is not None:
            try:
                shutil.rmtree(temp_dir)
            except OSError:
                pass

    return {"success": success, "fail": fail, "log": log}


def export_vtf_to_tga(queue, vtfcmd, output_dir):
    """将 VTF 文件导出为 TGA 法线贴图。

    queue: list[dict]，每个 dict 包含 vmt_name, vtf_path, rel
    vtfcmd: str, output_dir: str
    返回: dict{success: int, fail: int, log: list[str]}
    """
    log = []
    vtfcmd = Path(vtfcmd)
    output_dir = Path(output_dir)
    if not vtfcmd.is_file():
        return {"success": 0, "fail": 0, "log": [f"[错误] VTFCmd.exe 不存在: {vtfcmd}"]}

    success = fail = 0
    total = len(queue)
    for i, item in enumerate(queue):
        vtf = Path(item["vtf_path"])
        vmt_name = item.get("vmt_name", "?")
        tga_name = vtf.stem + ".tga"
        tga_path = output_dir / tga_name

        log.append(f"  {vmt_name}: {vtf.name} → {tga_name}")

        cmd = [str(vtfcmd), "-file", str(vtf), "-output", str(output_dir),
               "-exportformat", "tga", "-silent"]
        try:
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
        except (OSError, subprocess.TimeoutExpired) as e:
            log.append(f"    [失败] 调用 VTFCmd 出错: {e}")
            fail += 1
            continue

        if proc.returncode != 0 or not tga_path.exists():
            log.append(f"    [失败] VTFCmd 返回 {proc.returncode}")
            if proc.stderr.strip():
                log.append(f"    stderr: {proc.stderr.strip()}")
            fail += 1
            continue

        log.append(f"    [成功] -> {tga_path}")
        success += 1

    log.append(f"==== 导出完成：成功 {success}，失败 {fail} ====")
    return {"success": success, "fail": fail, "log": log}
